{
  "routingMode": "locale-prefix",
  "files": [
    {
      "path": "src/i18n/routing.ts",
      "description": "Defines supported locales and default locale for next-intl routing",
      "content": "import { defineRouting } from 'next-intl/routing';

export const routing = defineRouting({
  // All supported locales
  locales: ['es', 'en', 'pt'],

  // Default locale when no prefix is matched
  defaultLocale: 'es',

  // Uncomment to always show locale prefix in URLs (default: 'as-needed')
  // localePrefix: 'always',
});
"
    },
    {
      "path": "src/i18n/navigation.ts",
      "description": "Re-exports locale-aware navigation helpers (Link, redirect, usePathname, useRouter)",
      "content": "import { createNavigation } from 'next-intl/navigation';
import { routing } from './routing';

// Always import these from here instead of next/link or next/navigation.
// They automatically prefix hrefs with the active locale.
export const { Link, redirect, usePathname, useRouter, getPathname } =
  createNavigation(routing);
"
    },
    {
      "path": "src/i18n/request.ts",
      "description": "Server-side i18n config — validates locale against routing and loads messages",
      "content": "import { getRequestConfig } from 'next-intl/server';
import { hasLocale } from 'next-intl';
import { routing } from './routing';

export default getRequestConfig(async ({ requestLocale }) => {
  // requestLocale comes from the [locale] URL segment, negotiated by proxy.ts.
  const requested = await requestLocale;
  const locale = hasLocale(routing.locales, requested)
    ? requested
    : routing.defaultLocale;

  return {
    locale,
    messages: (await import(`../../messages/${locale}.json`)).default,
  };
});
"
    },
    {
      "path": "proxy.ts",
      "description": "Next.js 16+ proxy.ts — handles locale detection, negotiation, and URL rewriting. On Next.js ≤15 rename this file to middleware.ts and the function to middleware.",
      "content": "import createMiddleware from 'next-intl/middleware';
import type { NextRequest } from 'next/server';
import { routing } from './src/i18n/routing';

// next-intl locale negotiation handler
const intlProxy = createMiddleware(routing);

// Next.js 16+: this file is proxy.ts, exported function is `proxy`.
// On Next.js ≤15: rename this file to middleware.ts and this function to `middleware`.
export function proxy(request: NextRequest) {
  return intlProxy(request);
}

export const config = {
  // Match all pathnames except Next.js internals and static files.
  matcher: [
    '/((?!_next|_vercel|.*\\..*).*)',
    '/',
  ],
};
"
    },
    {
      "path": "next.config.ts",
      "description": "Next.js config with next-intl plugin",
      "content": "import type { NextConfig } from 'next';
import createNextIntlPlugin from 'next-intl/plugin';

const withNextIntl = createNextIntlPlugin(
  // Point to your request config file.
  './src/i18n/request.ts'
);

const nextConfig: NextConfig = {
  // Add your other Next.js config here.
};

export default withNextIntl(nextConfig);
"
    },
    {
      "path": "src/app/[locale]/layout.tsx",
      "description": "Root layout for the [locale] dynamic segment",
      "content": "import { NextIntlClientProvider, hasLocale } from 'next-intl';
import { notFound } from 'next/navigation';
import { routing } from '../../i18n/routing';
import type { ReactNode } from 'react';

interface Props {
  children: ReactNode;
  params: Promise<{ locale: string }>;
}

export default async function LocaleLayout({ children, params }: Props) {
  const { locale } = await params;

  // Reject unsupported locales with a 404
  if (!hasLocale(routing.locales, locale)) {
    notFound();
  }

  return (
    <html lang={locale}>
      <body>
        {/* NextIntlClientProvider makes messages available to Client Components */}
        <NextIntlClientProvider>
          {children}
        </NextIntlClientProvider>
      </body>
    </html>
  );
}
"
    },
    {
      "path": "messages/es.json",
      "description": "Message catalog for locale "es"",
      "content": "{
  "HomePage": {
    "title": "Welcome",
    "description": "This is the home page."
  }
}"
    },
    {
      "path": "messages/en.json",
      "description": "Message catalog for locale "en"",
      "content": "{
  "HomePage": {
    "title": "[EN] Welcome",
    "description": "[EN] This is the home page."
  }
}"
    },
    {
      "path": "messages/pt.json",
      "description": "Message catalog for locale "pt"",
      "content": "{
  "HomePage": {
    "title": "[PT] Welcome",
    "description": "[PT] This is the home page."
  }
}"
    }
  ],
  "setupSteps": [
    "1. Run: npm install next-intl",
    "2. Copy the generated files into your project.",
    "3. Move app/ to app/[locale]/ — keep your existing page.tsx and layout.tsx inside it.",
    "4. Replace next.config.(js|ts) with the generated next.config.ts.",
    "5. Place proxy.ts at the project root (same level as next.config.ts). This replaces middleware.ts in Next.js 16+.",
    "6. Start your dev server and open http://localhost:3000/es",
    "7. Import Link, useRouter, usePathname from src('i18n/navigation') (NOT from next/link or next/navigation).",
    "8. Server Components: const t = await getTranslations('Namespace')",
    "9. Client Components: const t = useTranslations('Namespace') — wrap with NextIntlClientProvider if needed.",
    "10. Full guide: https://next-intl.dev/docs/getting-started/app-router"
  ],
  "installCommand": "npm install next-intl"
}
